"use client";

import React, { useEffect, useMemo, useState } from "react";
import { api } from "@/lib/api";
import { useCurrentUser } from "@/hooks/use-current-user";
import { Appointment } from "@/types";

export default function AppointmentsPage() {
  const { currentUser, loading } = useCurrentUser();
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [currentMonth, setCurrentMonth] = useState(() => new Date());

  useEffect(() => {
    if (!currentUser) return;
    (async () => {
      const appts = await api.getAppointments(currentUser.tenantId);
      setAppointments(appts);
    })();
  }, [currentUser]);

  const { daysInMonth, startDay } = useMemo(() => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const first = new Date(year, month, 1);
    const last = new Date(year, month + 1, 0);
    const days: Date[] = [];
    for (let d = 1; d <= last.getDate(); d++) {
      days.push(new Date(year, month, d));
    }
    return {
      daysInMonth: days,
      startDay: first.getDay(),
    };
  }, [currentMonth]);

  function nextMonth() {
    setCurrentMonth(
      new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1)
    );
  }
  function prevMonth() {
    setCurrentMonth(
      new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1)
    );
  }

  function apptsFor(date: Date) {
    const iso = date.toISOString().split("T")[0];
    return appointments
      .filter((a) => a.date === iso)
      .sort((a, b) => a.startTime.localeCompare(b.startTime));
  }

  async function handleQuickAdd(date: Date) {
    if (!currentUser) return;
    const iso = date.toISOString().split("T")[0];
    const appt: Appointment = {
      id: `new-${Date.now()}`,
      title: "New appointment",
      client: "Walk-in",
      service: "General",
      date: iso,
      startTime: "10:00",
      endTime: "11:00",
    };
    await api.saveAppointment(currentUser.tenantId, appt);
    const appts = await api.getAppointments(currentUser.tenantId);
    setAppointments(appts);
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="h-8 w-8 rounded-full border-2 border-brand-primary border-t-transparent animate-spin" />
      </div>
    );
  }

  return (
    <div className="bg-dark-card rounded-xl border border-slate-800/40 h-[calc(100vh-7rem)] flex flex-col">
      <div className="p-4 flex items-center justify-between">
        <div>
          <h1 className="text-xl font-semibold text-white">
            {currentMonth.toLocaleString("default", {
              month: "long",
              year: "numeric",
            })}
          </h1>
          <p className="text-sm text-dark-text-secondary">
            Click a day to add a quick appointment
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={prevMonth}
            className="px-3 py-2 rounded-md bg-slate-800/50 text-white text-sm"
          >
            Prev
          </button>
          <button
            onClick={nextMonth}
            className="px-3 py-2 rounded-md bg-slate-800/50 text-white text-sm"
          >
            Next
          </button>
        </div>
      </div>
      <div className="grid grid-cols-7 text-center text-xs text-dark-text-secondary border-t border-slate-800/40">
        {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((d) => (
          <div key={d} className="py-3">
            {d}
          </div>
        ))}
      </div>
      <div className="grid grid-cols-7 flex-1 overflow-y-auto">
        {Array.from({ length: startDay }).map((_, i) => (
          <div key={`empty-${i}`} />
        ))}
        {daysInMonth.map((day) => {
          const todaysAppts = apptsFor(day);
          const isToday = (() => {
            const today = new Date();
            return (
              day.getDate() === today.getDate() &&
              day.getMonth() === today.getMonth() &&
              day.getFullYear() === today.getFullYear()
            );
          })();
          return (
            <button
              key={day.toISOString()}
              onClick={() => handleQuickAdd(day)}
              className="border border-slate-800/20 p-2 text-left hover:bg-slate-900/40 transition flex flex-col gap-2"
            >
              <span
                className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-sm ${
                  isToday ? "bg-brand-primary text-white" : "text-white"
                }`}
              >
                {day.getDate()}
              </span>
              <div className="space-y-1 overflow-y-auto max-h-24">
                {todaysAppts.map((a) => (
                  <div
                    key={a.id}
                    className="bg-brand-primary/20 text-brand-primary text-xs rounded px-2 py-1 truncate"
                  >
                    {a.startTime} • {a.title}
                  </div>
                ))}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}
